const NAME = /^[A-Za-z0-9_.-]+$/
const COST = /^[0-9]+$/

function checkName(name, line) {
  if (!NAME.test(name)) throw fail(`line ${line}: invalid task name ${name}`)
}

/**
 * Read the build graph out of the text of standard input.
 *
 * Returns { names, cost, deps } where names is the declaration order, cost maps
 * a name to its cost and deps maps a name to its de-duplicated dependencies.
 */
export function parseGraph(text) {
  const lines = text.split('\n')
  if (lines.length > 0 && lines[lines.length - 1] === '') lines.pop()

  const cost = new Map()
  const depLines = []

  for (let i = 0; i < lines.length; i += 1) {
    const lineNo = i + 1
    const trimmed = lines[i].trim()
    if (trimmed === '' || trimmed.startsWith('#')) continue
    const words = trimmed.split(/\s+/)

    if (words[0] === 'task') {
      if (words.length !== 3) throw fail(`line ${lineNo}: expected task <name> <cost>`)
      const [, name, raw] = words
      checkName(name, lineNo)
      if (!COST.test(raw)) throw fail(`line ${lineNo}: cost must be a non-negative integer`)
      if (cost.has(name)) throw fail(`line ${lineNo}: task ${name} is declared twice`)
      cost.set(name, Number(raw))
    } else if (words[0] === 'dep') {
      if (words.length < 3) throw fail(`line ${lineNo}: expected dep <name> <dependency>...`)
      for (const name of words.slice(1)) checkName(name, lineNo)
      depLines.push(words.slice(1))
    } else {
      throw fail(`line ${lineNo}: unknown directive ${words[0]}`)
    }
  }

  for (const words of depLines) {
    for (const name of words) {
      if (!cost.has(name)) throw fail(`unknown task ${name}`)
    }
  }

  const deps = new Map()
  for (const name of cost.keys()) deps.set(name, new Set())
  for (const [target, ...sources] of depLines) {
    for (const source of sources) deps.get(target).add(source)
  }

  const names = [...cost.keys()].sort(compareNames)
  const sortedDeps = new Map()
  for (const name of names) sortedDeps.set(name, [...deps.get(name)].sort(compareNames))

  return { names, cost, deps: sortedDeps }
}

/** Ascending name order. */
export function compareNames(a, b) {
  if (a < b) return -1
  if (a > b) return 1
  return 0
}
"}

