import { compareNames } from './parse.js'

/**
 * Report the first cycle a depth-first search finds, starting from each task in
 * ascending name order and walking each task's dependencies in ascending name
 * order. Throws when one exists.
 */
export function checkAcyclic(graph) {
  const { names, deps } = graph
  const state = new Map() // undefined: unvisited, 1: on the stack, 2: done
  const path = []
  const frames = []

  for (const root of names) {
    if (state.get(root) === 2) continue
    state.set(root, 1)
    path.push(root)
    frames.push({ name: root, list: deps.get(root), at: 0 })

    while (frames.length > 0) {
      const frame = frames[frames.length - 1]
      if (frame.at < frame.list.length) {
        const next = frame.list[frame.at]
        frame.at += 1
        const seen = state.get(next)
        if (seen === 1) {
          const start = path.indexOf(next)
          throw cycleError([...path.slice(start), next])
        }
        if (seen === undefined) {
          state.set(next, 1)
          path.push(next)
          frames.push({ name: next, list: deps.get(next), at: 0 })
        }
      } else {
        state.set(frame.name, 2)
        frames.pop()
        path.pop()
      }
    }
  }
}

/** Dependencies before dependents, in ascending name order at each step. */
export function topoOrder(graph) {
  const { names, deps } = graph
  const pending = new Map()
  const dependents = new Map()
  for (const name of names) dependents.set(name, [])
  for (const name of names) {
    pending.set(name, deps.get(name).length)
    for (const dep of deps.get(name)) dependents.get(dep).push(name)
  }

  const ready = names.filter((name) => pending.get(name) === 0)
  const order = []
  while (ready.length > 0) {
    ready.sort(compareNames)
    const name = ready.shift()
    order.push(name)
    for (const child of dependents.get(name)) {
      pending.set(child, pending.get(child) - 1)
      if (pending.get(child) === 0) ready.push(child)
    }
  }
  return { order, dependents }
}

/**
 * The schedule with unlimited workers: the depth (wave), start and finish of
 * every task, plus the priority used by the packer.
 */
export function analyse(graph) {
  const { names, cost, deps } = graph
  const { order, dependents } = topoOrder(graph)

  const depth = new Map()
  const start = new Map()
  const finish = new Map()
  for (const name of order) {
    let d = 0
    let s = 0
    let any = false
    for (const dep of deps.get(name)) {
      any = true
      d = Math.max(d, depth.get(dep) + 1)
      s = Math.max(s, finish.get(dep))
    }
    if (!any) d = 0
    depth.set(name, d)
    start.set(name, s)
    finish.set(name, s + cost.get(name))
  }

  const priority = new Map()
  for (let i = order.length - 1; i >= 0; i -= 1) {
    const name = order[i]
    let below = 0
    for (const child of dependents.get(name)) below = Math.max(below, priority.get(child))
    priority.set(name, cost.get(name) + below)
  }

  let total = 0
  for (const name of names) total = Math.max(total, finish.get(name))

  return { depth, start, finish, priority, dependents, total }
}
"}

