 * every task, plus the priority used by the packer.
 */
export function analyse(graph) {
  const { names, cost, deps } = graph
  const { order, dependents } = topoOrder(graph)

  const depth = new Map()
  const start = new Map()
  const finish = new Map()
  for (const name of order) {
    let d = 0
    let s = 0
    let any = false
    for (const dep of deps.get(name)) {
      any = true
      d = Math.max(d, depth.get(dep) + 1)
      s = Math.max(s, finish.get(dep))
    }
    if (!any) d = 0
    depth.set(name, d)
    start.set(name, s)
    finish.set(name, s + cost.get(name))
  }

  const priority = new Map()
  for (let i = order.length - 1; i >= 0; i -= 1) {
    const name = order[i]
    let below = 0
    for (const child of dependents.get(name)) below = Math.max(below, priority.get(child))
    priority.set(name, cost.get(name) + below)
  }

  let total = 0
  for (const name of names) total = Math.max(total, finish.get(name))

  return { depth, start, finish, priority, dependents, total }
}
"}

