{"file_path":"src/cli.js","content":"#!/usr/bin/env node
/**
 * The command. `node src/cli.js waves`, `node src/cli.js explain` and
 * `node src/cli.js pack <workers>` each report on the build graph read from
 * standard input.
 */
import { readFileSync } from 'node:fs'
import { fail } from './errors.js'
import { parseGraph } from './parse.js'
import { analyse, checkAcyclic } from './graph.js'
import { explain, waves } from './report.js'
import { pack } from './pack.js'

const USAGE = 'usage: cli.js waves|explain|pack <workers>'

/** Decide what to do from the command line arguments. */
function parseArgs(argv) {
  if (argv.length === 1 && (argv[0] === 'waves' || argv[0] === 'explain')) {
    return { mode: argv[0] }
  }
  if (argv.length === 2 && argv[0] === 'pack') {
    if (!/^[1-9][0-9]*$/.test(argv[1])) throw fail('workers must be a positive integer')
    return { mode: 'pack', workers: Number(argv[1]) }
  }
  throw fail(USAGE)
}

/** Read all of standard input as text. */
function readStdin() {
  try {
    return readFileSync(0, 'utf8')
  } catch {
    return ''
  }
}

function main() {
  const args = parseArgs(process.argv.slice(2))
  const graph = parseGraph(readStdin())
  checkAcyclic(graph)
  const info = analyse(graph)
  if (args.mode === 'waves') return waves(graph, info)
  if (args.mode === 'explain') return explain(graph, info)
  return pack(graph, info, args.workers)
}

try {
  process.stdout.write(main())
} catch (error) {
  if (error && error.exitCode) {
    process.stderr.write(`error: ${error.message}\n`)
    process.exit(error.exitCode)
  }
  throw error
}
"}

